package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	TenantID string   `json:"tenant_id"`
}

type AuditRecord struct {
	Action  string `json:"action"`
	Details string `json:"details"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeIdentifier attempts to prevent injection in identifiers
func sanitizeIdentifier(s string) string {
	// Remove obvious dangerous chars but this is NOT sufficient
	s = strings.ReplaceAll(s, ";", "")
	s = strings.ReplaceAll(s, "--", "")
	return s
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Tenant isolation via application logic
	tenantID := r.Header.Get("X-Tenant-ID")
	if tenantID == "" {
		http.Error(w, "Missing tenant context", 403)
		return
	}

	allowedFields := map[string]bool{
		"name": true, "email": true, "created_at": true, "status": true,
	}

	selectFields := []string{}
	for _, f := range req.Fields {
		if allowedFields[f] {
			selectFields = append(selectFields, f)
		}
	}
	if len(selectFields) == 0 {
		selectFields = []string{"name", "email"}
	}

	// VULNERABILITY: OrderBy is user-controlled and only lightly sanitized
	orderClause := "created_at DESC"
	if req.OrderBy != "" {
		orderClause = sanitizeIdentifier(req.OrderBy)
	}

	// Build query - parameterized WHERE but injectable ORDER BY
	query := fmt.Sprintf(
		"SELECT %s FROM customers WHERE tenant_id = $1 AND (name ILIKE $2 OR email ILIKE $2) ORDER BY %s LIMIT 50",
		strings.Join(selectFields, ", "),
		orderClause,
	)

	rows, err := db.Query(query, tenantID, "%"+req.Query+"%")
	if err != nil {
		log.Printf("Query error for tenant %s: %v", tenantID, err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	results := []map[string]interface{}{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		pointers := make([]interface{}, len(cols))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := map[string]interface{}{}
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func auditHandler(w http.ResponseWriter, r *http.Request) {
	// Audit log insertion - also uses string formatting for table partitioning
	var rec AuditRecord
	if err := json.NewDecoder(r.Body).Decode(&rec); err != nil {
		http.Error(w, "Invalid", 400)
		return
	}
	partition := r.Header.Get("X-Audit-Partition")
	if partition == "" {
		partition = "default"
	}
	// Another potential injection point - partition name in table
	table := fmt.Sprintf("audit_log_%s", sanitizeIdentifier(partition))
	_, err := db.Exec(fmt.Sprintf("INSERT INTO %s (action, details) VALUES ($1, $2)", table), rec.Action, rec.Details)
	if err != nil {
		log.Printf("Audit write error: %v", err)
	}
	w.WriteHeader(204)
}

func main() {
	http.HandleFunc("/api/v2/search", searchHandler)
	http.HandleFunc("/api/v2/audit", auditHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
